// src/pages/HomePage.jsx
import React from "react";
import { Link } from "react-router-dom";
import HeroSection from "../components/HeroSection";
import Features from "../components/Features";
import AboutSection from "../components/AboutSection";
import Footer from "../components/Footer";

const HomePage = () => {
  return (
    <div className="bg-gradient-to-b from-green-50 to-white min-h-screen flex flex-col">
      {/* Navbar */}
      <nav className="flex justify-between items-center p-6 shadow-md bg-white sticky top-0 z-50">
        <h1 className="text-2xl font-bold text-green-700">EcoPackAI</h1>
        <div className="space-x-6">
          <Link to="/login" className="text-gray-700 hover:text-green-600">Login</Link>
          <Link to="/register" className="text-gray-700 hover:text-green-600">Sign Up</Link>
          <Link to="/about" className="text-gray-700 hover:text-green-600">About</Link>
        </div>
      </nav>

      {/* Hero Section */}
      <HeroSection />

      {/* Features */}
      <Features />

      {/* About Section */}
      <AboutSection />

      {/* Footer */}
      <Footer />
    </div>
  );
};

export default HomePage;
